fn insert_source_snapshot(items: &mut BTreeMap<String, ContractRecord>) {
    let fields = [
        ("schema", "literal"),
        ("requirement_id", "string"),
        ("source_id", "string"),
        ("captured_at", "string"),
        ("source", "object"),
        ("content", "object"),
    ];
    let order: Vec<_> = fields.iter().map(|(name, _)| *name).collect();
    let description = json!({
        "schema": "work-contract-description/v1",
        "id": "work-source-snapshot/v1",
        "kind": "artifact",
        "caller_constructible": false,
        "required": order,
        "optional": [],
        "canonical_order": order,
        "fields": fields.iter().map(|(name, field_type)| json!({
            "name": name, "type": field_type, "required": true,
            "reference": null, "constraints": if *name == "source" {
                json!({"variants": {
                    "github_issue": {"required": ["kind", "repository", "number", "url"]},
                    "file": {"required": ["kind", "path", "media_type"],
                        "media_type": {"format": "RFC 6838 type/subtype without parameters",
                            "host_provided": true, "preserve_exact_value": true},
                        "example": {"kind":"file", "path":"原始需求.pdf", "media_type":"application/pdf"}},
                    "user_text": {"required": ["kind"]}
                }})
            } else { json!({}) }
        })).collect::<Vec<_>>(),
        "example": {
            "schema": "work-source-snapshot/v1",
            "requirement_id": "example",
            "source_id": "SRC-001",
            "captured_at": "2026-10-03T00:00:00Z",
            "source": {"kind": "user_text"},
            "content": {"path": "source.txt", "sha256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "size": 0}
        }
    });
    let record = json!({
        "description": description,
        "scaffold_error": {
            "reason_code": "contract_scaffold_requires_request",
            "message": "Only semantic request contracts have public input scaffolds.",
            "details": {"contract_id": "work-source-snapshot/v1", "kind": "artifact"}
        }
    });
    items.insert(
        "work-source-snapshot/v1".into(),
        serde_json::from_value(record).expect("valid Source Snapshot contract"),
    );
}

fn insert_source_responses(items: &mut BTreeMap<String, ContractRecord>) {
    let manifest = items["work-source-snapshot/v1"].description.example.clone();
    for (id, fields, example) in [
        (
            "work-source-read/v1",
            vec![
                ("schema", "literal", None),
                ("manifest", "object", Some("work-source-snapshot/v1")),
                ("bytes", "array<integer>", None),
            ],
            json!({"schema":"work-source-read/v1", "manifest":manifest, "bytes":[]}),
        ),
        (
            "work-source-validation/v1",
            vec![
                ("schema", "literal", None),
                ("status", "literal", None),
                ("requirement_id", "string", None),
                ("source_id", "string", None),
                ("content_sha256", "string", None),
                ("content_size", "integer", None),
            ],
            json!({"schema":"work-source-validation/v1", "status":"valid", "requirement_id":"example",
                "source_id":"SRC-001", "content_sha256":manifest["content"]["sha256"], "content_size":0}),
        ),
    ] {
        let order: Vec<_> = fields.iter().map(|(name, _, _)| *name).collect();
        let record = json!({"description": {
            "schema":"work-contract-description/v1", "id":id, "kind":"response", "caller_constructible":false,
            "required":order, "optional":[], "canonical_order":order,
            "fields":fields.iter().map(|(name, field_type, reference)| json!({
                "name":name, "type":field_type, "required":true, "reference":reference, "constraints":{}
            })).collect::<Vec<_>>(), "example":example
        }, "scaffold_error": {"reason_code":"contract_scaffold_requires_request",
            "message":"Only semantic request contracts have public input scaffolds.", "details":{"contract_id":id,"kind":"response"}}});
        items.insert(
            id.into(),
            serde_json::from_value(record).expect("valid Source response contract"),
        );
    }
}

